def find_ground_legs(origin_city="", destination_city="", limit=50):
    """Find DIRECTED GroundTransportLink legs for an (origin, destination) city pair, auto-trying the reverse pair (flagged) when absent.

    Args:
        origin_city (str): departure city (e.g., "Austin"); empty string skips this side.
        destination_city (str): arrival city (e.g., "Houston"); empty string skips this side.
        limit (int): maximum number of rows to return (default 50).

    Returns:
        list[dict]: up to `limit` rows with origin, destination, duration, distance
        (__id__/__type__ preserved) plus parsed duration_hours ('10 hours 55 mins' -> 10.92)
        and distance_km ('1,144 km' -> 1144). Lookup is indexed via from_city/to_city edges
        against City.name plus attribute matches, then a full scan fallback. Links are DIRECTED;
        if the exact ordered pair has no link, the reverse pair is tried and those rows carry
        reversed=True. Empty list if nothing matches either direction.

    Example:
        find_ground_legs("Austin", "Houston", limit=10)
    """
    o_raw = str(origin_city).strip()
    d_raw = str(destination_city).strip()
    o = o_raw.lower()
    d = d_raw.lower()
    if isinstance(limit, bool):
        lim = 50
    elif isinstance(limit, (int, float)):
        lim = int(limit)
    else:
        lim = 50
    if not o and not d:
        return []
    if lim <= 0:
        return []

    raw = {}
    if o:
        raw[o] = o_raw
    if d:
        raw[d] = d_raw

    # --- resolve City ids by normalized City.name (comma-tolerant exact match on the first component)
    city_ids = {}
    for want in (o, d):
        if want and want not in city_ids:
            ids = []
            for c in lookup_entities("City", {"name": raw[want]}, limit=200):
                cname = str(c.get("name", "")).strip().lower()
                c0 = cname.split(",")[0].strip()
                if cname == want or c0 == want or cname.startswith(want + ","):
                    cid = c.get("__id__")
                    if cid is not None:
                        ids.append(cid)
            city_ids[want] = ids

    # --- try ordered pair first; if absent (and both sides given), auto-try the reverse pair
    attempts = [(o, d)]
    if o and d and o != d:
        attempts.append((d, o))

    found = []
    reversed_mode = False
    for idx in range(len(attempts)):
        want_o, want_d = attempts[idx]
        reversed_mode = idx > 0

        cands = []
        seen = set()
        for cid in city_ids.get(want_o, []):
            for lg in traverse_relations(cid, "from_city", direction="in", max_hops=1):
                k = lg.get("__id__")
                if k is not None:
                    if k in seen:
                        continue
                    seen.add(k)
                cands.append(lg)
        for cid in city_ids.get(want_d, []):
            for lg in traverse_relations(cid, "to_city", direction="in", max_hops=1):
                k = lg.get("__id__")
                if k is not None:
                    if k in seen:
                        continue
                    seen.add(k)
                cands.append(lg)

        lookups = []
        f = {}
        if want_o:
            f["origin"] = raw.get(want_o, want_o)
        if want_d:
            f["destination"] = raw.get(want_d, want_d)
        if f:
            lookups.append(lookup_entities("GroundTransportLink", f, limit=20000))
        if want_o:
            lookups.append(lookup_entities("GroundTransportLink", {"origin": raw.get(want_o, want_o)}, limit=20000))
        if want_d:
            lookups.append(lookup_entities("GroundTransportLink", {"destination": raw.get(want_d, want_d)}, limit=20000))
        for rows in lookups:
            for r in rows:
                k = r.get("__id__")
                if k is not None:
                    if k in seen:
                        continue
                    seen.add(k)
                cands.append(r)

        # --- DIRECTED filter: origin must match want_o, destination must match want_d (if given)
        for r in cands:
            org = str(r.get("origin", "")).strip().lower()
            org0 = org.split(",")[0].strip()
            if want_o and not (org == want_o or org0 == want_o or org.startswith(want_o + ",")):
                continue
            dst = str(r.get("destination", "")).strip().lower()
            dst0 = dst.split(",")[0].strip()
            if want_d and not (dst == want_d or dst0 == want_d or dst.startswith(want_d + ",")):
                continue
            found.append(r)

        if not found:
            for r in lookup_entities("GroundTransportLink", None, limit=20000):
                org = str(r.get("origin", "")).strip().lower()
                org0 = org.split(",")[0].strip()
                if want_o and not (org == want_o or org0 == want_o or org.startswith(want_o + ",")):
                    continue
                dst = str(r.get("destination", "")).strip().lower()
                dst0 = dst.split(",")[0].strip()
                if want_d and not (dst == want_d or dst0 == want_d or dst.startswith(want_d + ",")):
                    continue
                found.append(r)

        if found:
            break

    out = project_properties(found, ["origin", "destination", "duration", "distance"])
    if len(out) > lim:
        out = out[:lim]

    # --- parse '10 hours 55 mins' -> duration_hours; '1,144 km' -> distance_km
    for row in out:
        if reversed_mode:
            row["reversed"] = True

        total_min = 0.0
        tokens = str(row.get("duration", "")).strip().lower().replace(",", "").split()
        for i, tok in enumerate(tokens):
            num = ""
            for ch in tok:
                if ch.isdigit() or ch == ".":
                    num += ch
                else:
                    break
            if not num or num == ".":
                continue
            val = float(num)
            unit = tok[len(num):].strip()
            if not unit and i + 1 < len(tokens):
                unit = tokens[i + 1]
            if unit.startswith("d"):
                total_min += val * 1440.0
            elif unit.startswith("h"):
                total_min += val * 60.0
            elif unit.startswith("m"):
                total_min += val
            elif unit.startswith("s"):
                total_min += val / 60.0
        row["duration_hours"] = round(total_min / 60.0, 2) if total_min > 0 else None

        km = None
        for tok in str(row.get("distance", "")).strip().lower().replace(",", "").split():
            num = ""
            for ch in tok:
                if ch.isdigit() or ch == ".":
                    num += ch
                else:
                    break
            if num and num != ".":
                km = int(round(float(num)))
                break
        row["distance_km"] = km

    return out

